// Manual pp.99,124: agricultural land and education-driven industrial change.
export const industrialJobs=t=>t.industry==='farm'?(t.farmRoot===t.y*48+t.x&&t.level?12:0):([0,1,3,8][t.level]||0)*12;
export const industryPollution=t=>t.industry==='clean'?.1:t.industry==='farm'?.03:1;
export const cleanThreshold=c=>Math.max(40,80-((c.startYear||1950)+Math.floor(c.month/12)-1900)*.175)-(c.civic.ordinances.cleanWater?10:0);
const chance=(c,t,offset=0)=>((Math.imul(t.x+37,73856093)^Math.imul(t.y+offset+17,19349663)^Math.imul(c.month+1,83492791)^c.seed)>>>0)/4294967296;
export function normalizeIndustry(c){const groups=new Map();for(const t of c.tiles){if(t.type!=='industrial'||!t.level&&!t.historicalLevel&&!t.abandonedLevel){t.industry='dirty';t.farmRoot=null;continue;}if(t.industry!=='farm'){t.farmRoot=null;continue;}if(!groups.has(t.farmRoot))groups.set(t.farmRoot,[]);groups.get(t.farmRoot).push(t);}for(const [root,members] of groups){const r=c.tiles[root];if(!r||r.industry!=='farm'||members.length!==9||members.some(t=>t.x<r.x||t.x>r.x+2||t.y<r.y||t.y>r.y+2||t.density!==1||t.radiation||t.rubble))for(const t of members){t.industry='dirty';t.farmRoot=null;}}}
export function farmCandidate(c,t){const n=Math.sqrt(c.tiles.length);if(t.x>n-3||t.y>n-3||!t.powered||!t.access)return null;const members=[];for(let y=t.y;y<t.y+3;y++)for(let x=t.x;x<t.x+3;x++)members.push(c.tiles[y*n+x]);if(members.some(u=>u.type!=='industrial'||u.level||u.historicalLevel||u.density!==1||u.radiation||u.rubble||u.fire||u.elevation!==t.elevation||u.landValue>60||u.airPollution>15||u.waterPollution>15))return null;const road=(x,y)=>x>=0&&y>=0&&x<n&&y<n&&(c.tiles[y*n+x].type==='road'||c.tiles[y*n+x].highway);const sides=[0,1,2,3].filter(side=>[0,1,2].some(k=>side===0?road(t.x+k,t.y-1):side===1?road(t.x+3,t.y+k):side===2?road(t.x+k,t.y+3):road(t.x-1,t.y+k)));return sides.length<3?members:null;}
export function advanceIndustry(c){normalizeIndustry(c);let farms=0,clean=0;for(const t of c.tiles){if(t.type!=='industrial'||t.historicalLevel)continue;if(t.industry==='farm'){if(t.landValue>68||t.airPollution>25||t.waterPollution>25){const root=t.farmRoot;for(const u of c.tiles)if(u.industry==='farm'&&u.farmRoot===root){u.industry='dirty';u.farmRoot=null;}}continue;}if(!t.level&&c.stats.demand.industrial>0&&chance(c,t)<.25){const members=farmCandidate(c,t);if(members){for(const u of members){u.industry='farm';u.farmRoot=t.y*48+t.x;u.level=1;u.abandonedLevel=0;u.age=0;u.stress=0;}farms++;continue;}}if(t.level&&t.industry!=='clean'&&t.powered&&t.access&&t.age>=6&&c.civic.education>=cleanThreshold(c)&&chance(c,t,97)<.2){t.industry='clean';clean++;}}return{farms,clean};}
export function industryStats(c){return{farms:c.tiles.filter(t=>t.industry==='farm'&&t.farmRoot===t.y*48+t.x).length,farmFields:c.tiles.filter(t=>t.industry==='farm').length,cleanIndustry:c.tiles.filter(t=>t.type==='industrial'&&t.level&&t.industry==='clean').length};}
